pub fn min_operations(nums: Vec<i32>) -> i32 {
    let n = nums.len();
    if n <= 1 {
        return 0;
    }

    let mut ops = 0;
    let mut prev = nums[0];

    for i in 1..n {
        if nums[i] <= prev {
            ops += prev - nums[i] + 1;
            prev += 1;
        } else {
            prev = nums[i];
        }
    }

    ops
}
